import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"@svta/cml-cmcd changelog","description":"","frontmatter":{},"headers":[],"relativePath":"packages/cmcd/changelog.md","filePath":"packages/cmcd/changelog.md"}`),a={name:`packages/cmcd/changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="svta-cml-cmcd-changelog" tabindex="-1">@svta/cml-cmcd changelog <a class="header-anchor" href="#svta-cml-cmcd-changelog" aria-label="Permalink to “@svta/cml-cmcd changelog”">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.8.4...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to “Unreleased”">​</a></h2><h2 id="_2-8-4-2026-10-26" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.8.3...cmcd-v2.8.4" target="_blank" rel="noreferrer">2.8.4</a> - 2026-10-26 <a class="header-anchor" href="#_2-8-4-2026-10-26" aria-label="Permalink to “2.8.4 - 2026-10-26”">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>recordResponseReceived</code> derives <code>ttfb</code> with <code>getTimeToFirstByte</code> from <code>@svta/cml-utils</code>. The report omits <code>ttfb</code> when <code>responseStart</code> is before <code>startTime</code> or after the end of the response, or when <code>duration</code> is missing. Before, the report held <code>responseStart - startTime</code> for any <code>responseStart</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/587" target="_blank" rel="noreferrer">#587</a>).</li><li>The <code>validateCmcdEventReport</code> doc now renders the example code block. The docs build no longer warns about the <code>@example</code> tag.</li><li>The README now has a When to use section. The section names the tasks that the package covers and the entry point of each task.</li><li>Every code example in the guides now typechecks. The <code>recordResponseReceived</code> examples now include <code>encodedBodySize</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/565" target="_blank" rel="noreferrer">#565</a>).</li></ul><h2 id="_2-8-3-2026-10-18" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.8.2...cmcd-v2.8.3" target="_blank" rel="noreferrer">2.8.3</a> - 2026-10-18 <a class="header-anchor" href="#_2-8-3-2026-10-18" aria-label="Permalink to “2.8.3 - 2026-10-18”">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Both overloads of <code>decodeCmcd</code>, <code>fromCmcdHeaders</code>, <code>fromCmcdQuery</code>, and <code>fromCmcdUrl</code> now have a doc comment.</li><li>The <code>CmcdTransformRequest</code> doc now links to <code>DeepReadonly</code> in <code>@svta/cml-utils</code>.</li><li>Peer dependency ranges are now caret ranges, for example <code>^1.6.2</code> instead of <code>1.6.2</code>. A later patch or minor release of a peer no longer requires a new release of this package.</li></ul><h2 id="_2-8-2-2026-10-08" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.8.1...cmcd-v2.8.2" target="_blank" rel="noreferrer">2.8.2</a> - 2026-10-08 <a class="header-anchor" href="#_2-8-2-2026-10-08" aria-label="Permalink to “2.8.2 - 2026-10-08”">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>dist/index.js</code> now parses as ES2021. A bundler no longer needs to transpile the package for an ES2021 target</li><li>A webpack bundle with a bare import of the package no longer contains code from the package</li></ul><h2 id="_2-8-1-2026-10-01" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.8.0...cmcd-v2.8.1" target="_blank" rel="noreferrer">2.8.1</a> - 2026-10-01 <a class="header-anchor" href="#_2-8-1-2026-10-01" aria-label="Permalink to “2.8.1 - 2026-10-01”">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The <code>CMCD</code> query parameter uses the encoding of the CTA-5004-B query examples. Only letters, digits, <code>-</code>, <code>.</code>, <code>_</code>, and <code>~</code> stay unencoded. A space becomes <code>%20</code>, and <code>(</code> and <code>)</code> become <code>%28</code> and <code>%29</code>. This is a wire output change. It covers <code>toCmcdUrl</code>, <code>toCmcdQuery</code>, <code>appendCmcdQuery</code>, and <code>CmcdReporter</code>. Before, <code>CmcdReporter</code> wrote a space as <code>+</code>, and the other functions sent <code>(</code> and <code>)</code> unencoded. A decoder that uses <code>URLSearchParams</code> reads the old and the new output as the same value. If a test compares exact URLs, update its expected strings. An unpaired surrogate in a string becomes U+FFFD. Before, it made <code>toCmcdUrl</code>, <code>toCmcdQuery</code>, and <code>appendCmcdQuery</code> throw <code>URIError</code></li><li><code>CmcdReporter</code> adds the <code>CMCD</code> query parameter and makes no other change to the request URL. Before, it parsed and serialized the whole URL. The serialization changed other query parameters, such as <code>~</code> to <code>%7E</code> and <code>flag</code> to <code>flag=</code>. It also lowercased the host, removed a default port, and resolved <code>./</code> and <code>../</code> in the path. A CDN that checks a token against the raw query could reject such a request. The <code>url</code> key of an <code>rr</code> event is the request URL without the <code>CMCD</code> parameter, also with no other change. <code>createRequestReport</code> and <code>recordResponseReceived</code> accept a relative URL. Before, they threw <code>Invalid URL</code></li><li><code>appendCmcdQuery</code> adds the parameter before the fragment. Before, it added the parameter after the fragment, so the request carried no CMCD data. It reads only the <code>CMCD</code> parameter of the query. Before, it replaced the value of a parameter such as <code>XCMCD</code>, or text that starts with <code>CMCD=</code> in the path. It removes every <code>CMCD</code> parameter after the first. If the data has no keys to send, it returns the URL unchanged. Before, it wrote a <code>CMCD</code> parameter with no value</li><li><code>fromCmcdUrl</code> decodes a <code>+</code> as a space, as <code>fromCmcdQuery</code> does. CTA-5004-B refers to the <code>application/x-www-form-urlencoded</code> format for the <code>CMCD</code> query argument. In this format, a <code>+</code> is a space. <code>CmcdReporter</code> 2.8.0 and earlier write a space as <code>+</code>. Before, <code>fromCmcdUrl</code> threw <code>failed to parse ... as Dict</code> for an inner list with two or more items, such as <code>nor=(&quot;a.m4s&quot; &quot;b.m4s&quot;)</code>. It decoded the string <code>&quot;a b&quot;</code> as <code>a+b</code>. A <code>%2B</code> still decodes as a <code>+</code></li></ul><h2 id="_2-8-0-2026-10-01" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.7.0...cmcd-v2.8.0" target="_blank" rel="noreferrer">2.8.0</a> - 2026-10-01 <a class="header-anchor" href="#_2-8-0-2026-10-01" aria-label="Permalink to “2.8.0 - 2026-10-01”">​</a></h2><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The encoder reads its key rules from one internal table. It no longer reads <code>CMCD_FORMATTER_MAP</code>. To change a value, use <code>CmcdEncodeOptions.formatters</code>. A formatter runs at most once in a call, and only for a key that the encoder can send. The <code>ot</code> and <code>e</code> formatters also run when a rule needs their value. The encoder no longer calls a <code>v</code> formatter. <code>CmcdReporter</code> applies the same rules and has no option to change them. <code>CMCD_FORMATTER_MAP</code> has an entry for each integer key and for <code>pr</code>. <code>prepareCmcdData</code> returns a symbol token as an <code>SfToken</code>. It returns a <code>nor</code> value that is one <code>SfItem</code> as a list. Both shapes give the same wire output as before</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The encoder applies the value rules of CTA-5004 and CTA-5004-B. This is a wire output change. It covers <code>prepareCmcdData</code>, <code>encodeCmcd</code>, <code>toCmcdHeaders</code>, <code>toCmcdQuery</code>, and <code>CmcdReporter</code>: <ul><li>It rounds every integer key, also inside an inner list with parameters. <code>tbl</code> rounds to 100 ms, like <code>bl</code>. A fractional <code>ts</code> and a <code>bl</code>, <code>br</code>, <code>mtp</code>, or <code>tb</code> list with parameters no longer make encoding throw</li><li>It drops a value of the wrong type and a number that is not finite. In a list, it drops only that element. It also drops a string over the maximum length of its key. In version 2, a custom string has at most 64 characters. A number that is not finite in the data of <code>CmcdReporter</code> made each later request report throw</li><li>It drops a plain object, a <code>Date</code>, or a byte sequence in a custom key. A plain object made encoding throw. It also drops an empty <code>nor</code> entry</li><li>It omits a default value with parameters, such as <code>pr=1;x</code>, as it omits the bare value</li><li>It reads the version from the value inside <code>v</code>, and it sends <code>v</code> without parameters</li><li>It ignores a <code>baseUrl</code> that is not a valid URL or that has an opaque origin. Before, it threw <code>Invalid URL</code></li><li>In version 1, an inner list becomes one value. The encoder selects the item by its object type flag, such as <code>br=(5000;v 320;a)</code>. An item without parameters matches any <code>ot</code>. If no item matches, the encoder omits the key</li><li>In version 1, <code>nor</code> sends its first item. The <code>r</code> parameter of that item becomes <code>nrr</code></li><li>In version 1, <code>cid</code> has at most 64 characters, and a custom string has no length limit. <code>st=ll</code> becomes <code>st=l</code>, and <code>sf=e</code> becomes <code>sf=o</code></li><li>In version 1, event mode sends only version 1 keys and custom keys</li><li>In version 2, one value on a list key is sent as a list. <code>br: 3000</code> becomes <code>br=(3000)</code></li><li>In version 2, <code>baseUrl</code> applies to a <code>nor</code> inner list with parameters. It also applies to a <code>nor</code> value that is one <code>SfItem</code></li><li>An <code>h</code> event carries <code>h</code>, also when the key filter removes it. In event mode, a report without <code>e</code> drops the response keys, such as <code>ttfb</code> and <code>url</code></li><li>The event rules and the object type rules read <code>e</code> and <code>ot</code> after their formatters. An event report keeps a <code>ts</code> with parameters</li></ul></li><li>The validators apply the rules of CTA-5004 and CTA-5004-B more closely. The changes cover <code>validateCmcd</code>, <code>validateCmcdRequest</code>, <code>validateCmcdHeaders</code>, <code>validateCmcdEvents</code>, <code>validateCmcdEventReport</code>, <code>validateCmcdStructure</code>, and <code>validateCmcdValues</code>: <ul><li>They accept a <code>b</code> event without <code>bg</code>, and <code>pr</code>, <code>c</code>, and <code>bc</code> events without their state keys. A <code>ps</code> event still requires <code>sta</code>. Its message now begins with &quot;Play state change event&quot;</li><li>A rounding rule stated with MUST gives an error, and a rule stated with SHOULD gives a warning. A payload that passed with a warning can now fail</li><li>They check the rounding of each element of a version 2 inner list. They also check that <code>br</code> and <code>tb</code> are integers</li><li>They accept a value with parameters, and they check the value inside its <code>SfItem</code></li></ul></li><li><code>decodeCmcd</code> with <code>convertToLatest</code> keeps an inner list with parameters, such as <code>br=(3000 6000);p=2</code>. Before, it put the list inside a second list, and the encoder dropped the key. A payload with parameters on <code>v</code>, such as <code>v=2;x</code>, no longer converts as version 1 data. The fix also applies to <code>fromCmcdHeaders</code>, <code>fromCmcdQuery</code>, and <code>fromCmcdUrl</code></li><li><code>CmcdReporter</code>: <ul><li><code>recordResponseReceived()</code> again reports a response without a provenance record, under the current session, as in version 2.4.0. Since version 2.6.0, hls.js and dash.js lost every <code>rr</code> event</li><li>The exit from backgrounded mode is a <code>b</code> event without <code>bg</code>. The reporter sent <code>bg=?0</code>. A receiver that checks for the key read <code>bg=?0</code> as an entry. This is a wire output change. If a receiver reads the exit from <code>bg=?0</code>, change it to accept a <code>b</code> event without <code>bg</code>. A target transform can add <code>bg: false</code> to send <code>bg=?0</code>. <code>encodeCmcd</code> still writes <code>bg: false</code> on a <code>b</code> event as <code>?0</code></li><li>A first <code>bg: false</code> in a session fires no <code>b</code> event. A transform that sets <code>bg: false</code> on an entry report no longer turns it into an exit</li><li><code>update()</code> accepts a <code>br</code> inner list with parameters. It threw <code>v.slice is not a function</code>. A <code>BITRATE_CHANGE</code> event fires only when a bitrate or an object type flag changes</li></ul></li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to “Documentation”">​</a></h3><ul><li>The user guide describes the value that <code>decodeCmcd</code> returns for a member with parameters. It also lists the values that the encoder drops and the version 1 limits. The TSDoc of <code>CmcdReporter.recordEvent</code> and <code>CmcdReportConfig.enabledKeys</code> no longer says that CTA-5004-B requires a key on every state-change event</li></ul><h2 id="_2-7-0-2026-09-15" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.6.1...cmcd-v2.7.0" target="_blank" rel="noreferrer">2.7.0</a> - 2026-09-15 <a class="header-anchor" href="#_2-7-0-2026-09-15" aria-label="Permalink to “2.7.0 - 2026-09-15”">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to “Changed”">​</a></h3><ul><li>TSDoc: the comment prose is rewritten for readers who do not read English as a first language. Signatures, examples, tags, and links are unchanged. Some comments had wrong facts. The <code>appendCmcdHeaders</code> summary said query args. The <code>isCmcdResponseReceivedKey</code> return description said request key. The <code>CmcdEventType</code> constants called their values keys. The <code>CmcdV1</code> <code>mtp</code> title had a stray key name.</li><li>The <code>Cmcd</code> type documentation links to the CTA-5004-B specification. It linked only to the version 1 PDF</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>A bare import of the package no longer runs code at module scope. <code>CmcdReporter</code> built its required-event-key table with an array spread of <code>CMCD_STATE_EVENT_FIELDS</code>. <code>prepareCmcdData</code> built its key filter table with computed keys. Bundlers kept one or both tables in every bundle that imports the package, even when the bundle uses neither function</li><li><code>validateCmcdRequest</code> reports an error when a request carries CMCD data in both the headers and the <code>CMCD</code> query parameter. CTA-5004-B allows one transmission mode per request. The validator still checks the headers and returns their data</li><li><code>validateCmcdRequest</code> reads the <code>CMCD</code> parameter from the query string and ignores the URL fragment. A relative URL no longer throws. When the fragment is the only place with a <code>CMCD</code> parameter, the error message says so</li><li>The encoder applies the &quot;MUST NOT&quot; rules of CTA-5004-B to version 2 payloads. The change covers <code>encodeCmcd</code>, <code>toCmcdHeaders</code>, <code>toCmcdQuery</code>, and <code>CmcdReporter</code>, which share <code>prepareCmcdData</code></li><li><code>d</code> is sent only when <code>ot</code> is <code>a</code>, <code>v</code>, <code>av</code>, <code>tt</code>, <code>c</code>, or <code>o</code>. <code>tpb</code> is sent only when <code>ot</code> is <code>a</code>, <code>v</code>, <code>av</code>, or <code>c</code>. The check reads the formatted <code>ot</code> from the data, even when <code>ot</code> is filtered out of the report. An absent or empty <code>ot</code> does not remove either key. CTA-5004 (version 1) has no such rule, so version 1 payloads are unchanged</li><li><code>ab</code>, <code>lab</code>, and <code>tab</code> are omitted when <code>br</code>, <code>lb</code>, or <code>tb</code> is sent in the same payload. The check runs after formatting, so a formatter that empties the exact key keeps the aggregate key</li><li><code>cen</code> is omitted unless the event type is <code>ce</code></li><li>An empty value is omitted instead of formatted. <code>null</code> on <code>br</code>, <code>d</code>, <code>bl</code>, <code>dl</code>, <code>mtp</code>, <code>rtp</code>, or <code>tb</code> was sent as <code>0</code>. <code>&#39;&#39;</code> on <code>nor</code> was sent as <code>nor=(&quot;&quot;)</code>. A custom formatter is no longer called for an empty value</li><li>An empty array is omitted. <code>br: []</code> was sent as <code>br=()</code></li><li><code>CmcdReporter</code> event report bodies no longer end with a line feed. CTA-5004-B separates records with a single line feed and forbids a trailing one</li><li><code>validateCmcdStructure</code> reports an error when <code>d</code> or <code>tpb</code> is present with an <code>ot</code> that the key does not allow. It also reports an error when <code>ab</code>, <code>lab</code>, or <code>tab</code> is present with <code>br</code>, <code>lb</code>, or <code>tb</code>. The message names the keys and the allowed object types. The checks apply to version 2 payloads and run in every validator</li><li><code>validateCmcdEvents</code> and <code>validateCmcdEventReport</code> report an error when the body ends with a line feed. Every earlier <code>CmcdReporter</code> sent that line feed. A receiver that upgrades marks reports from those players as invalid</li><li><code>nor</code> is the shortest relative path when the request URL and <code>baseUrl</code> share two or more leading path segments. A <code>baseUrl</code> directory such as <code>/v/1080p/</code> produced <code>nor=(&quot;../1080p/seg-2.m4s&quot;)</code> for a segment in the same directory. The value is now <code>nor=(&quot;seg-2.m4s&quot;)</code>. A value that is empty, starts with <code>/</code>, or has <code>:</code> in its first segment gets a <code>./</code> prefix. This is a wire output change</li></ul><h2 id="_2-6-1-2026-09-07" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.6.0...cmcd-v2.6.1" target="_blank" rel="noreferrer">2.6.1</a> - 2026-09-07 <a class="header-anchor" href="#_2-6-1-2026-09-07" aria-label="Permalink to “2.6.1 - 2026-09-07”">​</a></h2><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>encodeCmcd</code> now writes a token field as a bare token when its value is an <code>SfItem</code> that wraps a string. The token fields are <code>ot</code>, <code>sf</code>, <code>st</code>, <code>e</code>, and <code>sta</code>. <code>decodeCmcd</code> returns that shape for a member with parameters, such as <code>ot=m;com.example-p=1</code>. The encoder wrote the field as a quoted string, which is not valid CMCD (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/419" target="_blank" rel="noreferrer">#419</a>)</li><li><code>encodeCmcd</code> compares the <code>e</code> value by token text. <code>decodeCmcd</code> with <code>useSymbol</code> returns <code>e</code> as a <code>Symbol</code> or an <code>SfToken</code>. Such an event report now keeps its response-received keys on <code>e=rr</code>, <code>bg=?0</code> on <code>e=b</code>, and <code>pr=1</code> on <code>e=pr</code>. The version 1 down-conversion also matches the <code>ot</code> parameter of an inner-list item by token text (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/419" target="_blank" rel="noreferrer">#419</a>)</li><li><code>validateCmcdValues</code> accepts a token field whose value is an <code>SfItem</code>, a <code>Symbol</code>, or an <code>SfToken</code>. Since 2.6.0, <code>validateCmcdEvents</code> and the other string validators rejected a valid member such as <code>ot=m;com.example-p=1</code>. The message was <code>invalid token value &quot;[object Object]&quot;</code>. <code>validateCmcdStructure</code> applies the event rules (<code>cen</code>, <code>url</code>, response keys, state-change fields, <code>ec</code>) when <code>e</code> is a <code>Symbol</code> or an <code>SfToken</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/419" target="_blank" rel="noreferrer">#419</a>)</li></ul><h2 id="_2-6-0-2026-09-03" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.5.0...cmcd-v2.6.0" target="_blank" rel="noreferrer">2.6.0</a> - 2026-09-03 <a class="header-anchor" href="#_2-6-0-2026-09-03" aria-label="Permalink to “2.6.0 - 2026-09-03”">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li><p><code>CmcdReporterConfig.sessionRetention</code> — the number of ended sessions the reporter retains state for, in addition to the current one (default <code>2</code>; <code>0</code> disables retention, <code>Infinity</code> never evicts; only <code>number</code> values are accepted and floored, anything else falls back to the default). The reporter now keeps per-session state (data snapshot, sequence numbers, <code>msd</code> gate, dedup baseline, unsent queues) for recently ended sessions, so a media request that completes after a <code>sid</code> change reports under the session that issued it: its own <code>sid</code>, its next per-target sequence number, its still-unsent <code>msd</code>, and its frozen data snapshot, which is detached at the transition so mutating an array previously passed to <code>update()</code> cannot rewrite an ended session&#39;s late reports. A <code>sid</code> change also drains an ended session&#39;s unsent event reports (each keeps its own <code>sid</code> and sequence number) before eviction can discard them. Implements the accepted RFC in <code>rfc/cmcd-session-retention.md</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/pull/416" target="_blank" rel="noreferrer">#416</a>)</p></li><li><p><code>CMCD_REQUEST_PROVENANCE</code> — the symbol key (backed by <code>Symbol.for(&#39;@svta/cml-cmcd/request-provenance&#39;)</code>) under which <code>createRequestReport()</code> stamps a frozen session-provenance record (<code>CmcdRequestProvenance</code>) on every request it returns, including requests it does not decorate (request reporting disabled, or a transform cancels decoration). The record carries <code>sid</code>, the issuing session&#39;s ID and the attribution key; <code>cid</code>, the content ID in effect when the request was issued; and <code>data</code>, the request&#39;s per-call data encoded as a CMCD string, captured before the key filter and transform run so it rides undecorated requests too. <code>recordResponseReceived()</code> attributes by the record&#39;s <code>sid</code>, and only by it: a response whose record does not name a retained session is dropped rather than relabeled, and a per-call <code>data.sid</code> is not an attribution key. The record is honored wherever its <code>sid</code> resolves, so a hand-built record attributes, as does a split topology where one reporter decorates and another configured with the same session records. Session identity is the <code>sid</code> itself, which CTA-5004-B expects to be unique per playback session: reusing one replaces the retained namesake and relabels its late responses onto the replacement. The <code>RESPONSE_RECEIVED</code> event is rebuilt from the record: the decoded per-call snapshot supplies the caller&#39;s request-time report keys (never re-ingesting the player-facing, player-mutable <code>customData.cmcd</code> object, so token-typed values like <code>ot</code>, <code>sf</code>, <code>st</code>, and custom-key <code>SfToken</code>s keep their RFC 8941 wire type across serialization boundaries), and the record&#39;s <code>cid</code> reports in place of the session&#39;s current one, so a response that completes after a mid-session content change keeps the meaning it had when its request was issued. Spread and <code>Object.assign</code> carry the record through request clones; <code>JSON.stringify</code> and structured clone drop symbol keys, so read the value before such a boundary and restore it afterward — the record itself survives JSON and is read by value rather than object identity, so a revived copy behaves exactly like the original. The member is typed optional on <code>CmcdRequestReport</code> so the type stays constructible by consumers; every request the reporter returns carries it (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/pull/416" target="_blank" rel="noreferrer">#416</a>)</p></li><li><p><code>CmcdDecodeOptions.useSymbol</code> — controls how RFC 8941 token values are represented by <code>decodeCmcd</code> (and <code>fromCmcdQuery</code>/<code>fromCmcdHeaders</code>/<code>fromCmcdUrl</code>). When omitted, tokens reduce to plain strings as before, which cannot be told apart from string values on re-encoding. <code>true</code> decodes tokens as registry <code>Symbol</code>s, <code>false</code> as <code>SfToken</code> instances; either preserved representation re-encodes as a bare token, making the codec symmetric: <code>encodeCmcd(decodeCmcd(s, { useSymbol: false }))</code> returns the input bytes. <code>CmcdReporter</code> decodes provenance snapshots this way, so request-time token values keep their wire type on <code>RESPONSE_RECEIVED</code> reports</p></li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to “Changed”">​</a></h3><ul><li>README: the <code>CmcdReportRecorder</code> paragraph is rewritten for readers who do not read English as a first language. The code examples are unchanged.</li><li>User Guide, Report Recorder Guide, and Validation Guide: the prose is rewritten for readers who do not read English as a first language. The code examples and tables are unchanged.</li><li>User Guide and Validation Guide: one heading, one table cell, and one code comment no longer use a contraction or an em dash.</li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>decodeCmcd</code> no longer discards RFC 8941 parameters carried on a dictionary member or an inner list (<code>com.example-x=1;p=2</code>, <code>tab=(3000);p=2</code>): a params-bearing member now decodes as an <code>SfItem</code> with its value reduced as usual, matching how inner-list members with params were already preserved. The value inside a params-bearing item is also reduced consistently now (previously an inner token leaked as a raw <code>Symbol</code> instead of a string). Affects <code>decodeCmcd</code>, <code>fromCmcdQuery</code>, <code>fromCmcdHeaders</code>, and <code>fromCmcdUrl</code></li><li><code>CmcdReporter</code> event reports are encoded when they are queued rather than when a batch is sent. A report whose values cannot be serialized (RFC 8941 rejects them) now throws synchronously from the recording call that produced it, attributable to its caller, instead of rejecting the asynchronous batch send, where the failure was swallowed by the retry path and the un-encodable report re-queued forever, silently blocking every later report on batched targets. Queued reports are also finished wire bytes, immune to later mutation of caller-held values, so the per-target deep copy of report data is now made only where a <code>transform</code> is configured</li><li><code>CmcdReporter</code> now stamps the session-owned keys <code>sid</code> and <code>msd</code> after per-call data and transforms in both reporting modes, so neither <code>recordEvent()</code>/<code>recordResponseReceived()</code>/<code>createRequestReport()</code> data nor a <code>transform</code> return value can substitute the session ID or put <code>msd</code> on the wire outside the once-per-session gate. Transforms still see the canonical <code>sid</code> in their input. This also makes <code>update({ sid: undefined })</code> a no-op; previously the explicit <code>undefined</code> was merged into the data store and every later report went out with no <code>sid</code> at all. On <code>recordResponseReceived()</code> per-call session keys have no effect either: attribution is by the request&#39;s provenance record alone (see Added) (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/408" target="_blank" rel="noreferrer">#408</a>)</li><li><code>msd</code> lifecycle fixes (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/409" target="_blank" rel="noreferrer">#409</a>): <ul><li><code>update({ msd })</code> now accepts <code>0</code> (a valid instant-start value), rounds fractional values to integer milliseconds per CTA-5004-B, and rejects <code>Infinity</code>, negatives, <code>NaN</code>, and values whose rounded form exceeds the RFC 8941 structured-field integer maximum of <code>999_999_999_999_999</code>. Previously <code>0</code> was rejected while fractions and negatives reached the wire as-is; an accepted <code>Infinity</code> consumed the once-per-session gate without ever being encodable, so <code>msd</code> was silently never sent; and an over-range value consumed the gate and then threw in the serializer, poisoning event batches on every retry</li><li>A <code>sid</code> change now clears the stored <code>msd</code> and re-arms every send gate: <code>msd</code> is once per Session ID, so a value supplied for the new session is sent again, and a stored-but-unsent value from the old session no longer leaks forward</li><li>The send gate is consumed only when the prepared report actually retains <code>msd</code>. Previously both modes flipped the flag before the <code>enabledKeys</code> filter ran, so a target that filtered <code>msd</code> out still consumed its gate</li></ul></li><li>HTTP 410 disposal of an event target is now scoped per CTA-5004-B: suppression covers every event target configured with the matching URL, lasts for the remainder of the session that received the 410, and no longer outlives it. A <code>sid</code> change restores disposed targets (re-arming their intervals when the reporter is started), a 410 response that resolves after a session change silences the session that sent the batch instead of the one that replaced it, and a batch re-queued after a 429/5xx failure retries only within its own session, so a batch invalidated by a disposal in an ended session is never replayed into the new one (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/410" target="_blank" rel="noreferrer">#410</a>)</li><li>Corrected the <code>CmcdEncodeOptions.version</code> documentation, which still claimed a default of <code>1</code>. Encoding has defaulted to <code>CMCD_V2</code> since 2.0.0: when <code>version</code> is not set, the version is inferred from the data&#39;s <code>v</code> key, falling back to <code>CMCD_V2</code>, which is why <code>encodeCmcd({ br: 1000 })</code> emits <code>br=1000,v=2</code>. Documentation-only change; runtime behavior is unchanged</li></ul><h2 id="_2-5-0-2026-07-28" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.4.1...cmcd-v2.5.0" target="_blank" rel="noreferrer">2.5.0</a> - 2026-07-28 <a class="header-anchor" href="#_2-5-0-2026-07-28" aria-label="Permalink to “2.5.0 - 2026-07-28”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li><p><code>transform</code> on the request-report config and on each event-target config: a synchronous <code>(data, request) =&gt; Cmcd | null</code> hook that modifies a single CMCD report before it goes to the wire, or cancels it by returning <code>null</code>. Placement scopes the hook the same way <code>enabledKeys</code> does — the top-level <code>transform</code> applies to <code>createRequestReport()</code> reports, and each event target&#39;s <code>transform</code> applies to that target&#39;s event reports, so targets sharing a collector URL can filter independently. For <code>RESPONSE_RECEIVED</code> events the transform also receives the request that triggered them, which is how a player filters reports by its own request taxonomy on <code>customData</code>. Implements the accepted RFC in <code>rfc/cmcd-reporter-middleware.md</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/pull/390" target="_blank" rel="noreferrer">#390</a>)</p><p>The contract is bounded so a transform cannot produce an invalid or cross-contaminated report:</p><ul><li><code>e</code>, <code>sn</code>, and <code>msd</code> are stamped after the transform runs, so a cancelled report leaves no sequence-number gap and <code>msd</code> rides the next report that is sent.</li><li>Keys the event requires (<code>ts</code> always, the signalled field for state-change events, <code>cen</code> for custom events, <code>ec</code> for errors, <code>url</code> for response-received) are restored if a transform removes them, so a transform cannot emit a report <code>validateCmcdEvents()</code> would reject. Keys already absent beforehand are not fabricated.</li><li>The report data is copied for each target, nested values included, so mutating an array or an <code>SfItem</code>&#39;s <code>params</code> in place cannot reach the reporter&#39;s persistent data or another target&#39;s report.</li><li>Transform exceptions propagate rather than being swallowed, but are isolated per target: the remaining targets still receive the report and the error surfaces after the reporter finishes the event. This covers <code>start()</code>&#39;s initial time-interval event as well as <code>recordEvent()</code>, so a throwing transform cannot leave later targets without armed intervals. See the user guide.</li><li>The <code>request</code> argument is a read-only view (<code>CmcdTransformRequest</code>): it is context for the decision and must not be mutated, since it belongs to the caller. Members are <code>readonly</code>, and <code>customData</code> values are <code>unknown</code> unless the reporter is given the player&#39;s <code>customData</code> type (see below). A mutable <code>FormData</code>/<code>URLSearchParams</code> body and JavaScript callers are outside what the type can enforce</li></ul></li><li><p><code>CmcdReporterConfig.customHeaderMap</code> — routes custom keys into specific CMCD header shards (<code>CMCD-Session</code>, <code>CMCD-Object</code>, <code>CMCD-Status</code>) when the transmission mode is <code>HEADERS</code>. Custom keys not listed in any shard still default to <code>CMCD-Request</code>; standard keys keep their spec-defined shards and cannot be re-routed. The option previously existed on <code>CmcdEncodeOptions</code> but was not reachable through <code>CmcdReporter</code></p></li></ul><h3 id="fixed-6" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-6" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>prepareCmcdData</code> now force-includes <code>ec</code> on error events and <code>url</code> on response-received events after the per-target <code>enabledKeys</code> filter, completing the set started in 2.4.0 for state-change fields and <code>cen</code>. A target whose <code>enabledKeys</code> omitted <code>ec</code> previously emitted <code>e=e,sid=&quot;…&quot;,sn=0,ts=…,v=2</code>, which <code>validateCmcdEvents()</code> rejects for the missing required key; <code>rr</code> targets lost <code>url</code> the same way. This affects any such target, with or without a report transform configured</li></ul><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to “Changed”">​</a></h3><ul><li><p><code>CmcdTransformRequest</code>, <code>CmcdRequestReportTransform</code>, <code>CmcdEventReportTransform</code>, <code>CmcdRequestReportConfig</code>, <code>CmcdEventReportConfig</code>, <code>CmcdReporterConfig</code>, and <code>CmcdReporter</code> now take a type parameter describing the player&#39;s <code>customData</code>, so a transform reads player fields with typed dot access instead of bracket access on <code>unknown</code>. The parameter is inferred from the configuration: annotating a single transform as <code>CmcdEventReportTransform&lt;PlayerData&gt;</code> types the <code>request</code> argument in every other transform on the same reporter, and <code>new CmcdReporter&lt;PlayerData&gt;({ … })</code> does the same explicitly. Every declaration defaults to <code>Record&lt;string, unknown&gt;</code>, so existing code compiles unchanged and un-parameterized spellings such as <code>CmcdRequestReportTransform</code> keep their current <code>unknown</code>-valued behavior. This closes the asymmetry left by the generic <code>recordResponseReceived()</code> below, where the call site preserved the player&#39;s <code>customData</code> type but the transform reading that same request did not</p><p><code>customData</code> is readonly at every depth rather than only at the top level, so describing a nested shape does not trade the request&#39;s no-mutation guarantee for typed reads. <code>Readonly&lt;C&gt;</code> would have left <code>request.customData.nested.field = …</code> compiling, which the opaque-record default had always rejected</p><p><code>createRequestReport()</code> and <code>recordResponseReceived()</code> require the request&#39;s <code>customData</code> to satisfy the reporter&#39;s type, so a request the configured transforms could not read is rejected at the call site instead of reaching them and reading <code>undefined</code>. A reporter left on the default constrains nothing and accepts any <code>customData</code>, exactly as before; the rule is expressed by the new <code>CmcdReporterCustomData</code> type</p></li><li><p><code>CmcdReporterCustomData&lt;C&gt;</code> — the <code>customData</code> a <code>CmcdReporter</code> method accepts for a reporter typed <code>C</code>. Exported because it appears in the signatures of <code>createRequestReport()</code> and <code>recordResponseReceived()</code></p></li><li><p><code>CmcdReporter.recordResponseReceived()</code> is now generic over the request&#39;s <code>customData</code>, so a player can pass a request carrying only its own keys (e.g. <code>{ requestType: &#39;segment&#39; }</code>) without declaring a <code>cmcd</code> key it does not own and without a cast. The parameter was previously pinned to <code>HttpResponse&lt;HttpRequest&lt;{ cmcd?: Cmcd }&gt;&gt;</code>; because <code>{ cmcd?: Cmcd }</code> is a weak type (every property optional), a <code>customData</code> sharing no properties with it was rejected outright. This pairs with the per-target <code>transform</code>, which reads the player&#39;s taxonomy off the triggering request. Type-only widening: the reporter still reads just <code>customData.cmcd</code>, and existing callers passing <code>HttpRequest&lt;{ cmcd?: Cmcd }&gt;</code> continue to compile</p></li><li><p><code>isCmcdCustomKey</code> and the <code>CmcdCustomKey</code> type now only accept custom keys that survive RFC 8941 key serialization: a lowercase first letter, then characters from <code>a-z 0-9 . -</code>, with a hyphen that is neither the first nor the last character. Uppercase and digit-leading names were never serializable as CMCD; they are now rejected by the type, the validators, and key filtering instead of being dropped at encode preparation</p></li></ul><h3 id="documentation-1" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-1" aria-label="Permalink to “Documentation”">​</a></h3><ul><li>The user guide now documents custom reverse-DNS keys end to end: naming rules (including the runtime constraints the <code>CmcdCustomKey</code> type cannot express), the explicit <code>enabledKeys</code> opt-in required in both request mode and per event target (no wildcard exists), value types and wire-format behavior (<code>true</code> as a bare key, <code>false</code> dropped), and the fixed <code>CMCD-Request</code> header placement in headers mode</li><li>The custom-event (<code>e=ce</code>) documentation now shows a complete working configuration: <code>CmcdEventType.CUSTOM_EVENT</code> must be listed in the target&#39;s <code>events</code> for delivery, <code>cen</code> is force-included without an <code>enabledKeys</code> entry, and any accompanying payload remains subject to the target&#39;s <code>enabledKeys</code>. Also documents that response-received keys are stripped from non-<code>rr</code> events</li><li>The user guide and validation guide custom-key sections now cross-link each other</li></ul><h2 id="_2-4-1-2026-07-21" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.4.0...cmcd-v2.4.1" target="_blank" rel="noreferrer">2.4.1</a> - 2026-07-21 <a class="header-anchor" href="#_2-4-1-2026-07-21" aria-label="Permalink to “2.4.1 - 2026-07-21”">​</a></h2><h3 id="fixed-7" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-7" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Module-scope key-table <code>Set</code>/<code>Map</code> initializers (and the <code>CmcdReporter</code> state-field tables) are now marked side-effect free so consumer bundlers can drop them when unused; a bare import of the package previously retained ~4.9 KB of eagerly-built tables (follow-up to the module-scope side-effect audit in <a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/382" target="_blank" rel="noreferrer">#382</a>)</li><li><code>isCmcdCustomKey</code> no longer backtracks quadratically on hostile inputs (CodeQL polynomial ReDoS): the ambiguous regex was replaced with an unambiguous character-class check plus an interior-hyphen test; accepted inputs are unchanged (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/388" target="_blank" rel="noreferrer">#388</a>)</li></ul><h3 id="documentation-2" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-2" aria-label="Permalink to “Documentation”">​</a></h3><ul><li>Clarify recommended event-firing patterns in <code>CmcdReporter</code>: state-change events are fired via <code>update()</code>, with snapshot context attached by combining the state field and continuous metrics in a single call. <code>recordEvent()</code>&#39;s <code>data</code> argument is documented as intended for non-state-change events (custom, error, ad-lifecycle, mute/unmute, expand/collapse, skip). Calling <code>recordEvent()</code> for a state-change event after <code>update()</code> has auto-fired it silently drops the second call&#39;s data; see the user guide for the recommended pattern.</li></ul><h2 id="_2-4-0-2026-05-22" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.3.2...cmcd-v2.4.0" target="_blank" rel="noreferrer">2.4.0</a> - 2026-05-22 <a class="header-anchor" href="#_2-4-0-2026-05-22" aria-label="Permalink to “2.4.0 - 2026-05-22”">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>CmcdEventType.PLAYBACK_RATE</code> (token <code>&#39;pr&#39;</code>) for playback-rate-change events, per CTA-5004-B.</li><li><code>CmcdReportRecorder</code> — test helper that records CMCD-bearing reports across XHR and fetch transports for assertion in e2e tests. Includes <code>waitForReports</code>, <code>waitForManifest</code>, <code>waitForSegments</code>, and <code>waitForEvents</code> wait primitives that accept a <code>CmcdReportRecorderWaitOptions</code> object (<code>{ count?, timeout? }</code>, <code>count</code> defaults to <code>1</code>, reject on timeout) plus a <code>waitTimeout</code> attach option that sets the per-recorder default timeout, and event-target POST stubbing.</li><li><code>CmcdRecordedRequestType</code> const-enum and supporting types (<code>CmcdRecordedReport</code>, <code>CmcdRecordedReportMode</code>, <code>CmcdTransportAdapter</code>, <code>CmcdReportRecorderOptions</code>, <code>CmcdReportRecorderWaitOptions</code>).</li><li><code>createXhrTransport</code> and <code>createFetchTransport</code> default adapter factories.</li></ul><h3 id="changed-6" tabindex="-1">Changed <a class="header-anchor" href="#changed-6" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>CmcdReporter.update()</code> now auto-fires the corresponding state-change event (<code>PLAY_STATE</code>, <code>PLAYBACK_RATE</code>, <code>CONTENT_ID</code>, <code>BACKGROUNDED_MODE</code>, <code>BITRATE_CHANGE</code>) when a tracked field&#39;s value changes. A subsequent <code>recordEvent()</code> call for the same state-change event is deduplicated, which silently drops any enrichment data passed to it.</li><li><code>CmcdReporter.recordEvent()</code> with a state-change event now persists the dedup field from its <code>data</code> argument into the persistent data store (write-through), keeping <code>this.data</code> consistent with the most recently reported value.</li><li>Consecutive state-change events with the same effective field value are now suppressed, matching CTA-5004-B&#39;s definition of these events as state transitions.</li></ul><h3 id="fixed-8" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-8" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>prepareCmcdData</code> now force-includes the required field (<code>sta</code>, <code>pr</code>, <code>cid</code>, <code>bg</code>, <code>br</code>) for state-change events (<code>ps</code>, <code>pr</code>, <code>c</code>, <code>b</code>, <code>bc</code>) after the per-target <code>enabledKeys</code> filter, preventing CTA-5004-B-non-compliant payloads like <code>e=ps</code> with no <code>sta</code> (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/368" target="_blank" rel="noreferrer">#368</a>).</li><li><code>prepareCmcdData</code> preserves <code>pr=1</code> when encoding an <code>e=pr</code> state-change event in event mode. The v1 default-omission for <code>pr=1</code> still applies in request mode and in non-<code>pr</code> event-mode payloads.</li><li><code>prepareCmcdData</code> now emits an explicit <code>?0</code> token for <code>bg: false</code> on a backgrounded-mode (<code>e=b</code>) state-change event in event mode. Previously the field was stripped by the <code>isValid</code> filter, producing a CTA-5004-B-non-compliant payload on backgrounded-mode exit. The carve-out is scoped tightly to this case (<code>bg</code> is the only state-change required field typed as boolean); <code>&#39;&#39;</code>/nullish/<code>NaN</code> and <code>false</code> on other state-change required fields remain stripped, and request-mode default-omission is unchanged (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/372" target="_blank" rel="noreferrer">#372</a>).</li><li><code>validateCmcdStructure</code> now reports missing required fields for all five state-change events; previously only <code>e=ps</code> was checked for <code>sta</code>.</li></ul><h2 id="_2-3-2-2026-05-13" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.3.1...cmcd-v2.3.2" target="_blank" rel="noreferrer">2.3.2</a> - 2026-05-13 <a class="header-anchor" href="#_2-3-2-2026-05-13" aria-label="Permalink to “2.3.2 - 2026-05-13”">​</a></h2><h3 id="fixed-9" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-9" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Fix <code>nor</code> formatter crash (<code>TypeError: Invalid URL</code>) when the value is already a relative path and <code>baseUrl</code> is configured (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/364" target="_blank" rel="noreferrer">#364</a>)</li></ul><h3 id="changed-7" tabindex="-1">Changed <a class="header-anchor" href="#changed-7" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>CmcdReporter</code> now uses the current request URL&#39;s directory (via <code>getBaseUrl</code>) as the base for <code>nor</code> relative-path conversion, producing sibling-relative paths per the CMCD specification (previously the origin was used, yielding root-relative paths)</li><li>Clarify TSDoc for <code>nor</code> and <code>CmcdEncodeOptions.baseUrl</code> / <code>CmcdFormatterOptions.baseUrl</code> to document the absolute-URL convenience conversion</li></ul><h2 id="_2-3-1-2026-04-30" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.3.0...cmcd-v2.3.1" target="_blank" rel="noreferrer">2.3.1</a> - 2026-04-30 <a class="header-anchor" href="#_2-3-1-2026-04-30" aria-label="Permalink to “2.3.1 - 2026-04-30”">​</a></h2><h3 id="fixed-10" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-10" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Fix memory leak in <code>CmcdReporter</code> from orphaned <code>setInterval</code> after HTTP 410 response (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/360" target="_blank" rel="noreferrer">#360</a>)</li><li>Fix <code>CmcdReporter.start()</code> not being idempotent — repeated calls leaked the previous time-interval timer</li></ul><h2 id="_2-3-0-2026-03-12" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.2.0...cmcd-v2.3.0" target="_blank" rel="noreferrer">2.3.0</a> - 2026-03-12 <a class="header-anchor" href="#_2-3-0-2026-03-12" aria-label="Permalink to “2.3.0 - 2026-03-12”">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to “Added”">​</a></h3><ul><li>Add <code>CMCD_MIME_TYPE</code> constant for the CMCD event report MIME type</li><li>Add <code>validateCmcdEventReport(request, options?)</code> to validate full HTTP requests as event-mode payloads</li><li>Add <code>@see</code> links to JSDoc comments referencing CTA-5004-B spec sections</li></ul><h3 id="changed-8" tabindex="-1">Changed <a class="header-anchor" href="#changed-8" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Update event report MIME type from <code>text/cmcd</code> to <code>application/cmcd</code> per CTA-5004-B spec (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/332" target="_blank" rel="noreferrer">#332</a>)</li></ul><h2 id="_2-2-0-2026-02-18" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.1.2...cmcd-v2.2.0" target="_blank" rel="noreferrer">2.2.0</a> - 2026-02-18 <a class="header-anchor" href="#_2-2-0-2026-02-18" aria-label="Permalink to “2.2.0 - 2026-02-18”">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to “Added”">​</a></h3><ul><li>Add <code>validateCmcd(data, options?)</code> orchestrator that runs key, value, and structure validation</li><li>Add <code>validateCmcdKeys(data, options?)</code> to check keys against recognized v1/v2 spec keys</li><li>Add <code>validateCmcdValues(data, options?)</code> to validate value types, constraints, and rounding rules</li><li>Add <code>validateCmcdStructure(data, options?)</code> to validate structural rules (event mode, version key, response-received keys)</li><li>Add <code>validateCmcdHeaders(headers)</code> to validate CMCD HTTP headers including shard placement</li><li>Add <code>validateCmcdEvents(cmcd)</code> to validate multi-line event-mode payloads</li><li>Add <code>validateCmcdRequest(request)</code> to validate CMCD data from a <code>Request</code> or <code>HttpRequest</code></li><li>Add <code>CmcdValidationResult</code>, <code>CmcdDataValidationResult</code>, <code>CmcdEventsValidationResult</code>, <code>CmcdValidationIssue</code>, <code>CmcdValidationOptions</code>, and <code>CmcdValidationSeverity</code> types</li><li>Add <code>CmcdData</code>, <code>CmcdV1Data</code>, and <code>CmcdV2Data</code> discriminated union types using <code>v</code> as the discriminator property</li><li>Add <code>isCmcdV1Data(data)</code> type guard to narrow <code>CmcdData</code> to <code>CmcdV1Data</code></li><li>Add <code>isCmcdV2Data(data)</code> type guard to narrow <code>CmcdData</code> to <code>CmcdV2Data</code></li><li>Add <code>CmcdDecodeOptions</code> type with <code>convertToLatest</code> option to up-convert v1 data to v2 format during decoding</li><li>Add optional <code>options</code> parameter to <code>decodeCmcd</code>, <code>fromCmcdHeaders</code>, <code>fromCmcdQuery</code>, and <code>fromCmcdUrl</code></li></ul><h3 id="changed-9" tabindex="-1">Changed <a class="header-anchor" href="#changed-9" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Change <code>decodeCmcd</code>, <code>fromCmcdHeaders</code>, <code>fromCmcdQuery</code>, and <code>fromCmcdUrl</code> return type from <code>Cmcd</code> to <code>CmcdData</code></li></ul><h3 id="fixed-11" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-11" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Fix <code>CMCD_EVENT_BITRATE_CHANGE</code> value from <code>&#39;br&#39;</code> to <code>&#39;bc&#39;</code></li></ul><h2 id="_2-1-2-2026-02-11" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.1.1...cmcd-v2.1.2" target="_blank" rel="noreferrer">2.1.2</a> - 2026-02-11 <a class="header-anchor" href="#_2-1-2-2026-02-11" aria-label="Permalink to “2.1.2 - 2026-02-11”">​</a></h2><h3 id="changed-10" tabindex="-1">Changed <a class="header-anchor" href="#changed-10" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Improve TSDoc for <code>CmcdReporter</code> methods</li><li>Update <code>@svta/cml-utils</code> to 1.4.0</li></ul><h2 id="_2-1-1-2026-02-09" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.1.0...cmcd-v2.1.1" target="_blank" rel="noreferrer">2.1.1</a> - 2026-02-09 <a class="header-anchor" href="#_2-1-1-2026-02-09" aria-label="Permalink to “2.1.1 - 2026-02-09”">​</a></h2><h3 id="fixed-12" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-12" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Fix <code>CmcdReporter.start()</code> dispatching time interval events to all targets instead of only the target with the event enabled</li></ul><h2 id="_2-1-0-2026-02-06" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.0.1...cmcd-v2.1.0" target="_blank" rel="noreferrer">2.1.0</a> - 2026-02-06 <a class="header-anchor" href="#_2-1-0-2026-02-06" aria-label="Permalink to “2.1.0 - 2026-02-06”">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to “Added”">​</a></h3><ul><li>Add <code>CmcdReporter.recordResponseReceived(response, data?)</code> method for automated <code>rr</code> event reporting</li><li>Add <code>CmcdReporter.createRequestReport(request, data?)</code> method with generic type support and per-request CMCD data</li><li>Add <code>CmcdReporter.isRequestReportingEnabled()</code> method to check if request reporting is enabled</li><li>Add <code>CmcdRequestReport</code> type</li></ul><h3 id="changed-11" tabindex="-1">Changed <a class="header-anchor" href="#changed-11" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>CmcdReporter.recordEvent</code> data parameter is now scoped to the event instead of being persisted via <code>update()</code></li><li><code>CmcdReporter.recordEvent</code> now respects caller-supplied <code>ts</code> values instead of always overriding with <code>Date.now()</code></li><li><code>CmcdReporter.stop</code> now accepts an optional <code>flush</code> parameter</li></ul><h3 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to “Deprecated”">​</a></h3><ul><li><code>CmcdReporter.applyRequestReport</code> in favor of <code>CmcdReporter.createRequestReport</code></li></ul><h2 id="_2-0-1-2026-02-04" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v2.0.0...cmcd-v2.0.1" target="_blank" rel="noreferrer">2.0.1</a> - 2026-02-04 <a class="header-anchor" href="#_2-0-1-2026-02-04" aria-label="Permalink to “2.0.1 - 2026-02-04”">​</a></h2><h3 id="changed-12" tabindex="-1">Changed <a class="header-anchor" href="#changed-12" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Update <code>@svta/cml-structured-field-values</code> to 1.1.1</li><li>Update <code>@svta/cml-utils</code> to 1.3.0</li><li>Update <code>CmcdReporter</code> to use <code>HttpRequest</code> from <code>@svta/cml-utils</code> (renamed from <code>Request</code>)</li></ul><h3 id="fixed-13" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-13" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Missing <code>CmcdVersion</code> and <code>CMCD_HEADER_MAP</code> exports</li></ul><h2 id="_2-0-0-2026-02-03" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v1.0.2...cmcd-v2.0.0" target="_blank" rel="noreferrer">2.0.0</a> - 2026-02-03 <a class="header-anchor" href="#_2-0-0-2026-02-03" aria-label="Permalink to “2.0.0 - 2026-02-03”">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to “Added”">​</a></h3><ul><li>CMCD Version 2 support (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/143" target="_blank" rel="noreferrer">#143</a>)</li></ul><h2 id="_1-0-2-2025-12-26" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v1.0.1...cmcd-v1.0.2" target="_blank" rel="noreferrer">1.0.2</a> - 2025-12-26 <a class="header-anchor" href="#_1-0-2-2025-12-26" aria-label="Permalink to “1.0.2 - 2025-12-26”">​</a></h2><h3 id="changed-13" tabindex="-1">Changed <a class="header-anchor" href="#changed-13" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Update <code>@svta/cml-utils</code> to 1.1.0 (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/279" target="_blank" rel="noreferrer">#279</a>)</li></ul><h2 id="_1-0-1-2025-12-22" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/cmcd-v1.0.0...cmcd-v1.0.1" target="_blank" rel="noreferrer">1.0.1</a> - 2025-12-22 <a class="header-anchor" href="#_1-0-1-2025-12-22" aria-label="Permalink to “1.0.1 - 2025-12-22”">​</a></h2><h3 id="changed-14" tabindex="-1">Changed <a class="header-anchor" href="#changed-14" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Removed <code>response mode</code> from CMCD encoding</li><li>Added <code>response received</code> event and filtering</li></ul><h3 id="fixed-14" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-14" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>Use fixed version numbers for all CML peer dependencies (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/277" target="_blank" rel="noreferrer">#277</a>)</li></ul><h2 id="_1-0-0-2025-10-24" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/tree/cmcd-v1.0.0" target="_blank" rel="noreferrer">1.0.0</a> - 2025-10-24 <a class="header-anchor" href="#_1-0-0-2025-10-24" aria-label="Permalink to “1.0.0 - 2025-10-24”">​</a></h2><h3 id="changed-15" tabindex="-1">Changed <a class="header-anchor" href="#changed-15" aria-label="Permalink to “Changed”">​</a></h3><ul><li>Remove CommonJS exports (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/192" target="_blank" rel="noreferrer">#192</a>)</li><li>Convert to mono-repo (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/238" target="_blank" rel="noreferrer">#238</a>)</li><li>Produce single bundled export for each package (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/260" target="_blank" rel="noreferrer">#260</a>)</li></ul>`,111)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};